//! The ScriptWidget runtime for Linux, ported from
//! `Windows/src/ScriptWidget.Core` (itself a port of `Android/core`).
//!
//! It runs the same shared JavaScript as Android and Windows (generated by
//! `Linux/scripts/build-shared-js.mjs`) in the QuickJS-NG engine of the
//! `sw-quickjs` crate. Packages, scripts and everything they return are
//! untrusted: package code only ever runs in a fresh execution context that
//! reaches the host through the operations in [`executor`].

pub mod api;
pub mod compiler;
pub mod executor;
pub mod intl;
pub mod json;
pub mod package_files;
pub mod shared_scripts;

pub use compiler::{PackageCompiler, PreparedPackage, RuntimeError};
pub use executor::{Completion, ExecutionError, ExecutionRequest, ExecutionResult, ExecutionSession, LogEntry, NativeModule, ScriptExecutor};
pub use package_files::{MemoryPackageFiles, PackageFiles, normalize_package_path};
pub use shared_scripts::SharedScripts;
